#!/usr/bin/env python3
"""
ArdaBest RotS Complete Linux Installer (NO ROOT)
=================================================

Installs the complete pure-Python RotS MUD client for the current Linux user.
It never calls sudo, su, apt, dnf, pacman, zypper, apk, or another system
package manager, and it refuses to run as root.

The installed client includes:
- asyncio.open_connection() two-way Telnet socket
- async underwait() network reader
- valid XML traffic/event logs
- pure-Python regex aliases and triggers
- ordinary Python variables and pub/sub
- syntax-checked reloadable Python automation modules
- graphical NetworkX mapper with small/medium/large detail modes
- alternate-screen terminal mapper (minimum 80x24) with five info lines
- terrain colors, red X current location, and E: exit letters
- local ZeroMQ ROUTER map-query service
- automatic connection to rotsmud.org:3791

Normal use (do NOT use sudo):
    python3 install_ardabest_rots_complete_linux_no_root.py

No Y/N questions are asked.
"""
