class InstallError(RuntimeError):
    pass


def default_install_dir() -> Path:
    xdg = os.environ.get("XDG_DATA_HOME")
    base = Path(xdg).expanduser() if xdg else Path.home() / ".local" / "share"
    return base / "ardabest-rots-complete-client"


def default_bin_dir() -> Path:
    return Path.home() / ".local" / "bin"


def default_applications_dir() -> Path:
    xdg = os.environ.get("XDG_DATA_HOME")
    base = Path(xdg).expanduser() if xdg else Path.home() / ".local" / "share"
    return base / "applications"


def quote(value: str | Path) -> str:
    import shlex
    return shlex.quote(str(value))


def run(command: list[str], *, check: bool = True) -> subprocess.CompletedProcess[str]:
    print("> " + " ".join(quote(part) for part in command), flush=True)
    try:
        return subprocess.run(command, check=check, text=True)
    except FileNotFoundError as exc:
        raise InstallError(f"Required program was not found: {command[0]}") from exc
    except subprocess.CalledProcessError as exc:
        raise InstallError(f"Command failed with exit code {exc.returncode}: {command[0]}") from exc


def require_linux_non_root(*, dry_run: bool) -> None:
    if not sys.platform.startswith("linux"):
        raise InstallError("This installer is for Linux.")
    if sys.version_info < (3, 10):
        raise InstallError("Python 3.10 or newer is required.")
    if hasattr(os, "geteuid") and os.geteuid() == 0 and not dry_run:
        raise InstallError(
            "Do not run this installer with sudo or as root. Run it as your normal user:\n"
            "  python3 install_ardabest_rots_complete_linux_no_root.py"
        )


def verify_tkinter() -> None:
    try:
        import tkinter  # noqa: F401
    except Exception as exc:
        raise InstallError(
            "The graphical client needs a Python installation that includes Tk/Tcl. "
            "This no-root installer will not install system packages. Use a user-accessible "
            f"Python build with Tk and run the installer again. Python reported: {exc}"
        ) from exc


def decode_client() -> bytes:
    try:
        compact = "".join(PAYLOAD_B85.split())
        data = zlib.decompress(base64.b85decode(compact.encode("ascii")))
    except Exception as exc:
        raise InstallError(f"The embedded client payload is damaged: {exc}") from exc
    if hashlib.sha256(data).hexdigest() != CLIENT_SHA256:
        raise InstallError("The embedded client failed its SHA-256 integrity check.")
    return data


def write_atomic(path: Path, data: bytes, mode: int | None = None) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as tmp:
        tmp.write(data)
        tmp.flush()
        os.fsync(tmp.fileno())
        temporary = Path(tmp.name)
    temporary.replace(path)
    if mode is not None:
        path.chmod(mode)


def ensure_pip(python_exe: Path) -> None:
    result = subprocess.run(
        [str(python_exe), "-m", "pip", "--version"],
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    if result.returncode == 0:
        return
    result = subprocess.run([str(python_exe), "-m", "ensurepip", "--user", "--upgrade"], check=False)
    if result.returncode != 0:
        raise InstallError(
            "This Python installation has neither venv nor pip. The installer cannot alter "
            "system packages without root. Use a user-accessible Python with venv or pip."
        )


def make_python_environment(install_dir: Path, *, skip_dependencies: bool, dry_run: bool) -> tuple[Path, Path | None]:
    venv_dir = install_dir / ".venv"
    venv_python = venv_dir / "bin" / "python"
    if dry_run:
        print(f"Would create private environment: {venv_dir}")
        if not skip_dependencies:
            print("Would install privately: " + ", ".join(DEPENDENCIES))
        return venv_python, None

    if not venv_python.exists():
        print("Creating a private Python environment (no root)...", flush=True)
        result = subprocess.run([sys.executable, "-m", "venv", str(venv_dir)], check=False)
        if result.returncode != 0 or not venv_python.exists():
            print("venv is unavailable; using a private package directory instead.", flush=True)
            shutil.rmtree(venv_dir, ignore_errors=True)
            target = install_dir / "python-packages"
            target.mkdir(parents=True, exist_ok=True)
            base_python = Path(sys.executable)
            ensure_pip(base_python)
            if not skip_dependencies:
                run([
                    str(base_python), "-m", "pip", "install",
                    "--disable-pip-version-check", "--no-input", "--upgrade",
                    "--target", str(target), *DEPENDENCIES,
                ])
            return base_python, target

    if not skip_dependencies:
        print("Installing NetworkX, PyZMQ, and Prompt Toolkit privately...", flush=True)
        run([
            str(venv_python), "-m", "pip", "install",
            "--disable-pip-version-check", "--no-input", "--upgrade",
            *DEPENDENCIES,
        ])
    return venv_python, None


def launcher_body(python_exe: Path, client_path: Path, pythonpath: Path | None, mode_args: str) -> bytes:
    env_line = ""
    if pythonpath is not None:
        env_line = f"export PYTHONPATH={quote(pythonpath)}${PYTHONPATH:+:$PYTHONPATH}\n"
    return (
        "#!/bin/sh\n"
        "set -eu\n"
        + env_line
        + f"exec {quote(python_exe)} {quote(client_path)} {mode_args} --connect --host rotsmud.org --port 3791 \"$@\"\n"
    ).encode("utf-8")


def create_launchers(
    bin_dir: Path,
    python_exe: Path,
    client_path: Path,
    pythonpath: Path | None,
    *,
    dry_run: bool,
) -> tuple[Path, Path]:
    gui = bin_dir / "ardabest-rots"
    terminal = bin_dir / "ardabest-rots-terminal-map"
    if dry_run:
        print(f"Would create GUI launcher: {gui}")
        print(f"Would create terminal-map launcher: {terminal}")
    else:
        write_atomic(gui, launcher_body(python_exe, client_path, pythonpath, "--gui"), 0o755)
        write_atomic(terminal, launcher_body(python_exe, client_path, pythonpath, "--terminal-map"), 0o755)
    return gui, terminal


def create_desktop_entries(app_dir: Path, gui: Path, terminal: Path, *, dry_run: bool) -> tuple[Path, Path]:
    gui_entry = app_dir / "ardabest-rots.desktop"
    terminal_entry = app_dir / "ardabest-rots-terminal-map.desktop"
    gui_text = textwrap.dedent(f"""\
        [Desktop Entry]
        Type=Application
        Version=1.0
        Name=ArdaBest RotS MUD Client
        Comment=Pure-Python RotS client with a live NetworkX map
        Exec={gui}
        Icon=utilities-terminal
        Terminal=false
        Categories=Game;Network;
        StartupNotify=true
    """)
    terminal_text = textwrap.dedent(f"""\
        [Desktop Entry]
        Type=Application
        Version=1.0
        Name=ArdaBest RotS Terminal Map
        Comment=Alternate-screen 80x24 terminal mapper
        Exec={terminal}
        Icon=utilities-terminal
        Terminal=true
        Categories=Game;Network;
        StartupNotify=true
    """)
    if dry_run:
        print(f"Would create menu entries: {gui_entry}, {terminal_entry}")
    else:
        write_atomic(gui_entry, gui_text.encode("utf-8"), 0o644)
        write_atomic(terminal_entry, terminal_text.encode("utf-8"), 0o644)
        update = shutil.which("update-desktop-database")
        if update:
            subprocess.run([update, str(app_dir)], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return gui_entry, terminal_entry


def create_uninstaller(
    path: Path,
    install_dir: Path,
    launchers: tuple[Path, Path],
    desktop_entries: tuple[Path, Path],
    *,
    dry_run: bool,
) -> None:
    removals = "".join(f"rm -f {quote(p)}\n" for p in (*launchers, *desktop_entries))
    body = (
        "#!/bin/sh\nset -eu\n"
        + removals
        + f"rm -rf {quote(install_dir)}\n"
        + "printf '%s\n' 'ArdaBest application files removed.'\n"
        + "printf '%s\n' 'The profile remains in ~/.local/share/ardabest-python-profile.'\n"
    )
    if dry_run:
        print(f"Would create uninstaller: {path}")
    else:
        write_atomic(path, body.encode("utf-8"), 0o755)


def launch(gui_launcher: Path, *, no_launch: bool, dry_run: bool) -> None:
    if no_launch:
        return
    if not (os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY")):
        print("No graphical desktop session detected. Installation is complete; run ardabest-rots later.")
        return
    if dry_run:
        print(f"Would launch: {gui_launcher}")
        return
    subprocess.Popen(
        [str(gui_launcher)],
        cwd=str(gui_launcher.parent),
        start_new_session=True,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )


def parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Install the complete ArdaBest RotS client without root.")
    p.add_argument("--install-dir", type=Path, default=default_install_dir())
    p.add_argument("--no-launch", action="store_true")
    p.add_argument("--skip-dependencies", action="store_true")
    p.add_argument("--no-shortcuts", action="store_true")
    p.add_argument("--dry-run", action="store_true")
    return p


def main() -> int:
    args = parser().parse_args()
    try:
        require_linux_non_root(dry_run=args.dry_run)
        verify_tkinter()
        install_dir = args.install_dir.expanduser().resolve()
        client_path = install_dir / CLIENT_NAME
        print("=" * 74)
        print(APP_NAME + " — Linux no-root installer")
        print("No sudo, root, system package manager, or Y/N questions will be used.")
        print(f"Install directory: {install_dir}")
        print("=" * 74)

        if args.dry_run:
            print(f"Would write embedded client: {client_path}")
        else:
            install_dir.mkdir(parents=True, exist_ok=True)
            write_atomic(client_path, decode_client(), 0o755)

        python_exe, pythonpath = make_python_environment(
            install_dir,
            skip_dependencies=args.skip_dependencies,
            dry_run=args.dry_run,
        )

        if args.no_shortcuts:
            local_bin = install_dir
            app_dir = install_dir
        else:
            local_bin = default_bin_dir()
            app_dir = default_applications_dir()

        launchers = create_launchers(local_bin, python_exe, client_path, pythonpath, dry_run=args.dry_run)
        if args.no_shortcuts:
            desktop_entries = (install_dir / "unused-gui.desktop", install_dir / "unused-terminal.desktop")
        else:
            desktop_entries = create_desktop_entries(app_dir, *launchers, dry_run=args.dry_run)
        create_uninstaller(
            install_dir / "uninstall.sh",
            install_dir,
            launchers,
            desktop_entries,
            dry_run=args.dry_run,
        )

        print("\nINSTALLATION COMPLETE")
        print(f"GUI launcher:          {launchers[0]}")
        print(f"Terminal-map launcher: {launchers[1]}")
        print("Server:                rotsmud.org:3791")
        print("ZMQ ROUTER:            tcp://127.0.0.1:5555")
        print("Profile:               ~/.local/share/ardabest-python-profile")
        print("XML logs:              profile/logs/*.xml")
        print("No files were installed as root.")
        launch(launchers[0], no_launch=args.no_launch, dry_run=args.dry_run)
        return 0
    except KeyboardInterrupt:
        print("\nInstallation cancelled.", file=sys.stderr)
        return 130
    except InstallError as exc:
        print("\nINSTALLATION FAILED", file=sys.stderr)
        print(str(exc), file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"\nUnexpected installer error: {type(exc).__name__}: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
